import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import axios from 'axios';
import toast from 'react-hot-toast';

const Dashboard = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [stats, setStats] = useState({ totalProblems: 0, totalSubmissions: 0 });
  const [recentProblems, setRecentProblems] = useState([]);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:5000/api/problems', {
        headers: { Authorization: `Bearer ${token}` }
      });
      const problems = response.data.problems || [];
      setStats({ 
        totalProblems: problems.length,
        totalSubmissions: 0
      });
      setRecentProblems(problems.slice(0, 4));
    } catch (error) {
      console.error('Error fetching data:', error);
    }
  };

  const statCards = [
    { icon: '📚', label: 'Total Problems', value: stats.totalProblems, color: '#6C63FF' },
    { icon: '✅', label: 'Solved', value: user?.stats?.problemsSolved || 0, color: '#4CAF50' },
    { icon: '📝', label: 'Attempts', value: user?.stats?.totalAttempts || 0, color: '#FF9800' },
    { icon: '🏆', label: 'Success Rate', value: user?.stats?.totalAttempts > 0 
        ? Math.round((user.stats.problemsSolved / user.stats.totalAttempts) * 100) 
        : 0, color: '#E91E63', suffix: '%' },
  ];

  const quickActions = [
    { icon: '📚', label: 'Problems', path: '/problems', color: '#6C63FF' },
    { icon: '📊', label: 'Submissions', path: '/submissions', color: '#4CAF50' },
  ];

  if (user?.role === 'admin' || user?.role === 'setter') {
    quickActions.push({ icon: '➕', label: 'Create', path: '/create-problem', color: '#FF9800' });
  }

  return (
    <div style={styles.container}>
      {/* Sidebar */}
      <div style={styles.sidebar}>
        <div style={styles.logo}>
          <span style={styles.logoIcon}>⚡</span>
          <span style={styles.logoText}>CodeArena</span>
        </div>
        <div style={styles.sidebarMenu}>
          <div style={{...styles.menuItem, ...styles.menuItemActive}} onClick={() => navigate('/')}>
            <span>🏠</span> Dashboard
          </div>
          <div style={styles.menuItem} onClick={() => navigate('/problems')}>
            <span>📚</span> Problems
          </div>
          <div style={styles.menuItem} onClick={() => navigate('/submissions')}>
            <span>📊</span> Submissions
          </div>
          {(user?.role === 'admin' || user?.role === 'setter') && (
            <div style={styles.menuItem} onClick={() => navigate('/create-problem')}>
              <span>➕</span> Create
            </div>
          )}
          <div style={{...styles.menuItem, marginTop: 'auto'}} onClick={() => {
            localStorage.removeItem('token');
            localStorage.removeItem('user');
            navigate('/login');
          }}>
            <span>🚪</span> Logout
          </div>
        </div>
        <div style={styles.sidebarFooter}>
          <div style={styles.userInfo}>
            <div style={styles.userAvatar}>👤</div>
            <div>
              <div style={styles.userName}>{user?.username}</div>
              <div style={styles.userRole}>{user?.role}</div>
            </div>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div style={styles.mainContent}>
        {/* Top Bar */}
        <div style={styles.topBar}>
          <div>
            <h1 style={styles.pageTitle}>Dashboard</h1>
            <p style={styles.pageSubtitle}>Welcome back, {user?.username}! 👋</p>
          </div>
          <div style={styles.topBarActions}>
            <button style={styles.refreshBtn} onClick={() => window.location.reload()}>
              🔄 REFRESH
            </button>
            <div style={styles.weather}>
              <span>☀️</span> 29°
            </div>
          </div>
        </div>

        {/* Stats Cards */}
        <div style={styles.statsGrid}>
          {statCards.map((stat, index) => (
            <div key={index} style={styles.statCard}>
              <div style={{...styles.statIcon, background: stat.color + '20', color: stat.color}}>
                {stat.icon}
              </div>
              <div>
                <div style={styles.statValue}>{stat.value}{stat.suffix || ''}</div>
                <div style={styles.statLabel}>{stat.label}</div>
              </div>
            </div>
          ))}
        </div>

        {/* Quick Actions */}
        <div style={styles.quickActions}>
          <h3 style={styles.sectionTitle}>⚡ Quick Actions</h3>
          <div style={styles.actionGrid}>
            {quickActions.map((action, index) => (
              <div
                key={index}
                style={styles.actionCard}
                onClick={() => navigate(action.path)}
                onMouseEnter={(e) => e.currentTarget.style.transform = 'scale(1.05)'}
                onMouseLeave={(e) => e.currentTarget.style.transform = 'scale(1)'}
              >
                <div style={{...styles.actionIcon, background: action.color + '20', color: action.color}}>
                  {action.icon}
                </div>
                <div style={styles.actionLabel}>{action.label}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Recent Problems */}
        <div style={styles.recentSection}>
          <div style={styles.sectionHeader}>
            <h3 style={styles.sectionTitle}>📋 Recent Problems</h3>
            <button style={styles.viewAllBtn} onClick={() => navigate('/problems')}>
              View All →
            </button>
          </div>
          <div style={styles.problemGrid}>
            {recentProblems.length > 0 ? (
              recentProblems.map((problem) => (
                <div
                  key={problem._id}
                  style={styles.problemCard}
                  onClick={() => navigate(`/problems/${problem._id}`)}
                >
                  <div style={styles.problemHeader}>
                    <span style={styles.problemTitle}>{problem.title}</span>
                    <span style={{
                      ...styles.difficultyBadge,
                      background: problem.difficulty === 'Easy' ? '#4CAF50' :
                                 problem.difficulty === 'Medium' ? '#FF9800' : '#f44336',
                    }}>
                      {problem.difficulty || 'Easy'}
                    </span>
                  </div>
                  <p style={styles.problemDesc}>
                    {problem.description?.substring(0, 80)}...
                  </p>
                  <div style={styles.problemFooter}>
                    <span style={styles.problemDate}>
                      📅 {new Date(problem.createdAt).toLocaleDateString()}
                    </span>
                    <span style={styles.solveBtn}>Solve →</span>
                  </div>
                </div>
              ))
            ) : (
              <div style={styles.emptyState}>
                <div style={styles.emptyIcon}>📭</div>
                <p>No problems available</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

const styles = {
  container: {
    display: 'flex',
    minHeight: '100vh',
    background: '#f0f2f5',
    fontFamily: 'Inter, sans-serif',
  },
  sidebar: {
    width: '260px',
    background: '#1a1a2e',
    color: '#fff',
    padding: '24px 20px',
    display: 'flex',
    flexDirection: 'column',
    position: 'fixed',
    height: '100vh',
    boxShadow: '2px 0 20px rgba(0,0,0,0.1)',
  },
  logo: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    padding: '0 12px 30px 12px',
    borderBottom: '1px solid rgba(255,255,255,0.08)',
    marginBottom: '20px',
  },
  logoIcon: {
    fontSize: '28px',
  },
  logoText: {
    fontSize: '20px',
    fontWeight: 700,
    background: 'linear-gradient(135deg, #6C63FF, #FF6B6B)',
    WebkitBackgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
  },
  sidebarMenu: {
    display: 'flex',
    flexDirection: 'column',
    gap: '4px',
    flex: 1,
  },
  menuItem: {
    padding: '12px 16px',
    borderRadius: '12px',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    fontSize: '14px',
    fontWeight: 500,
    color: 'rgba(255,255,255,0.6)',
    transition: 'all 0.3s',
  },
  menuItemActive: {
    background: 'rgba(108, 99, 255, 0.2)',
    color: '#6C63FF',
  },
  sidebarFooter: {
    borderTop: '1px solid rgba(255,255,255,0.08)',
    paddingTop: '20px',
  },
  userInfo: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    padding: '8px 12px',
    borderRadius: '12px',
    background: 'rgba(255,255,255,0.05)',
  },
  userAvatar: {
    fontSize: '24px',
  },
  userName: {
    fontSize: '14px',
    fontWeight: 600,
  },
  userRole: {
    fontSize: '12px',
    color: 'rgba(255,255,255,0.5)',
    textTransform: 'capitalize',
  },
  mainContent: {
    marginLeft: '260px',
    flex: 1,
    padding: '24px 32px',
  },
  topBar: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '30px',
  },
  pageTitle: {
