    background: '#f8f9fa',
    textAlign: 'center',
    cursor: 'pointer',
    transition: 'all 0.3s',
    border: '1px solid transparent',
  },
  actionIcon: {
    width: '48px',
    height: '48px',
    borderRadius: '12px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontSize: '24px',
    margin: '0 auto 10px auto',
  },
  actionLabel: {
    fontSize: '14px',
    fontWeight: 500,
    color: '#1a1a2e',
  },
  recentSection: {
    background: 'white',
    padding: '24px',
    borderRadius: '16px',
    boxShadow: '0 2px 10px rgba(0,0,0,0.05)',
  },
  sectionHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '16px',
  },
  viewAllBtn: {
    padding: '6px 16px',
    background: 'transparent',
