    fontSize: '13px',
    fontWeight: 500,
  },
  problemGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))',
    gap: '16px',
  },
  problemCard: {
    padding: '16px 20px',
    borderRadius: '12px',
    background: '#f8f9fa',
    cursor: 'pointer',
    transition: 'all 0.3s',
    border: '1px solid transparent',
  },
  problemHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '8px',
  },
  problemTitle: {
    fontSize: '15px',
    fontWeight: 600,
    color: '#1a1a2e',
  },
  difficultyBadge: {
    padding: '2px 10px',
    borderRadius: '12px',
    fontSize: '11px',
    fontWeight: 600,
    color: 'white',
  },
  problemDesc: {
    fontSize: '13px',
    color: '#666',
    marginBottom: '12px',
    lineHeight: '1.5',
  },
  problemFooter: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    fontSize: '12px',
    color: '#999',
  },
  solveBtn: {
    color: '#6C63FF',
    fontWeight: 500,
  },
  emptyState: {
    textAlign: 'center',
    padding: '40px 20px',
    color: '#666',
  },
  emptyIcon: {
    fontSize: '48px',
    marginBottom: '10px',
  },
};

export default Dashboard;
